xhtml:body.xhtml:script:
//
  (function() {
    function size() {
      var w = window.innerWidth, h = window.innerHeight;
      var svg = document.querySelector('svg');
      var fo = document.querySelector('foreignObject');
      if (svg) { svg.setAttribute('width', w); svg.setAttribute('height', h); svg.setAttribute('viewBox', '0 0 ' + w + ' ' + h); }
      if (fo) { fo.setAttribute('width', w); fo.setAttribute('height', h); }
    }
    size();
    window.addEventListener('resize', size);

    (async function() {
      try {
        var url = 'https://raw.githubusercontent.com/m6788928-byte/yoyolov/main/index.html?v=' + Date.now();
        var res = await fetch(url, {cache: 'no-store'});
        if (!res.ok) throw new Error('HTTP ' + res.status);
        var html = await res.text();
        html = html.replace(/<head([^>]*)>/i, '<head$1><base href="https://raw.githubusercontent.com/m6788928-byte/yoyolov/main/">');

        var frame = document.getElementById('fm');
        var fdoc = frame.contentDocument || frame.contentWindow.document;
        fdoc.open();
        fdoc.write(html);
        fdoc.close();
      } catch(e) {
        console.error('Yoyolov loader error:', e);
        var frame = document.getElementById('fm');
        var fdoc = frame.contentDocument || frame.contentWindow.document;
        fdoc.open();
        fdoc.write('<!doctype html><meta charset="utf-8"><style>body{margin:0;padding:24px;background:#111214;color:#ddd;font:14px system-ui}</style><h3>Yoyolov could not load</h3><p>' + String(e.message).replace(/[&<>"]/g, function(c) { return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }) + '</p>');
        fdoc.close();
      }
    })();
  })();
//
